//! The scheduler C ABI, generated by bindgen from `include/scheduler.h`: change the header, not
//! this file. Enums arrive as integer constants; records carry generated layout assertions.

// Generated code follows C's naming and carries the whole surface, the declarations of the
// functions this crate defines included.
#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code
)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
